function Press({children,className='',...props}:React.ComponentProps<typeof Button>){return <Button className={'press '+className} {...props}>{children}</Button>}
function Field({id,label,type='text',value,hint,disabled=false,required=false}:{id:string,label:string,type?:string,value?:string,hint?:string,disabled?:boolean,required?:boolean}){return <label className="field" htmlFor={id}>{label}<Input id={id} type={type} defaultValue={value} disabled={disabled} required={required} minLength={type==='password'?8:undefined} maxLength={type==='password'?200:undefined} autoComplete={type==='password'?'new-password':type==='email'?'email':undefined}/>{hint&&<small>{hint}</small>}</label>}
function SelectField({label,id,children,value,onChange}:{label:string,id:string,children:React.ReactNode,value?:string,onChange?:(v:string)=>void}){return <label className="field" htmlFor={id}>{label}<select className="control" id={id} value={value} onChange={e=>onChange?.(e.target.value)}>{children}</select></label>}
function Note({children,kind='',title}:{children:React.ReactNode,kind?:string,title:string}){return <div className={'feedback '+kind} role={kind==='good'?'status':'alert'}><strong>{title}</strong><div>{children}</div></div>}
function Notice({en=false}:{en?:boolean}){return <div className="notice" lang={en?'en':'es'}><h3>{en?'Personal data notice':'Aviso de datos personales'}</h3><p>{en?'[CONTROLLER] uses your name, email and company to manage your account and provide the Pictures tools.':'[RESPONSABLE] usa tu nombre, correo y empresa para gestionar tu cuenta y ofrecer las herramientas de Pictures.'}</p><p>{en?'AI usage is recorded for cost tracking. You may request access, correction or deletion at [CONTACT]. [RETENTION] and [LEGAL BASIS] remain under legal review.':'El uso de IA se registra para medir costos. Puedes solicitar acceso, corrección o supresión en [CONTACTO]. [CONSERVACIÓN] y [BASE LEGAL] siguen en revisión jurídica.'}</p><span className="notice-version">{en?'Version 1 · Draft for legal review':'Versión 1 · Borrador en revisión jurídica'}</span></div>}
function Knot(){const profile=useMotionProfile();const [pull,setPull]=React.useState(0);return <div className="knot-area"><motion.div className="knot" drag={profile.reduced?false:'x'} dragConstraints={{left:-16,right:16}} dragSnapToOrigin dragElastic={.2} animate={{x:pull,rotate:pull/3}} transition={profile.reduced?{duration:0}:profile.spring} aria-hidden="true"><svg viewBox="0 0 360 220" fill="none"><g className="latex-loop"><path d="M78 162C-6 121 30 4 116 18C176 28 189 130 222 153C286 197 356 119 307 80C262 44 169 178 105 161Z" fill="var(--latex)" stroke="var(--ink)" strokeWidth="3"/><path d="M78 145C33 118 44 36 105 36" stroke="#fff5b4" strokeWidth="13" strokeLinecap="round"/><path d="M115 151C156 169 185 127 209 122" stroke="var(--seam)" strokeWidth="13" strokeLinecap="round"/><path d="M166 125C153 107 142 106 134 117L151 163C167 182 188 172 186 155Z" fill="var(--primary)" stroke="var(--ink)" strokeWidth="3"/></g></svg></motion.div><div className="knot-actions"><Press className="small" onClick={()=>setPull(Math.max(-14,pull-7))}>Soltar banda</Press><Press className="small" onClick={()=>setPull(Math.min(14,pull+7))}>Tensar banda</Press></div><p className="knot-note">Muestra de látex · puedes moverla. No cambia accesos.</p></div>}
